{"rawEvent":{"message_id":"019e2489518a7193babf432167efe286","conversation_id":"019e24746cf87e7bb37671ae61701f24","tool_call_id":"tooluse_cqNxU7UVJHhWmL39qghxkh","document":{"file_path":"/Users/garyznjiang/AndroidStudioProjects/other/个人/NgLeetCode/code/src/main/java/com/ng/code/util/FileUtil.java","sub_content":"FileUtil.java","sub_content_event":"open_editor","sub_content_event_value":"/Users/garyznjiang/AndroidStudioProjects/other/个人/NgLeetCode/code/src/main/java/com/ng/code/util/FileUtil.java","sub_content_tip":"/Users/garyznjiang/AndroidStudioProjects/other/个人/NgLeetCode/code/src/main/java/com/ng/code/util/FileUtil.java","old_string":" public static String getProjectPath() {
 Properties properties = new Properties();
 try {
 FileInputStream fileInputStream = new FileInputStream("local.properties"); // 根据项目结构修改路径
 properties.load(fileInputStream);
 } catch (Exception e) {
 e.printStackTrace();
 }
 String projectPath = properties.getProperty("projectpath");
 if (projectPath == null || projectPath.isEmpty()) {
 // 兜底：使用当前工作目录
 projectPath = new File("").getAbsolutePath();
 System.err.println("[FileUtil] projectpath 未在 local.properties 中配置，使用当前工作目录: " + projectPath);
 }
 return projectPath + "/";
 }
}","new_string":" public static String getProjectPath() {
 // 1) 优先从 working directory 下的 local.properties 读取
 String projectPath = readProjectPathFromLocalProperties(new File("local.properties"));

 // 2) 兜底：通过 FileUtil.class 的位置反推工程根目录，并尝试读其下的 local.properties
 if (projectPath == null || projectPath.isEmpty()) {
 String autoRoot = autoDetectProjectRoot();
 if (autoRoot != null) {
 String fromAuto = readProjectPathFromLocalProperties(new File(autoRoot, "local.properties"));
 if (fromAuto != null && !fromAuto.isEmpty()) {
 projectPath = fromAuto;
 } else {
 projectPath = autoRoot;
 System.err.println("[FileUtil] projectpath 未在 local.properties 中配置，使用自动探测的工程根目录: " + projectPath);
 }
 }
 }

 // 3) 最后兜底：当前工作目录
 if (projectPath == null || projectPath.isEmpty()) {
 projectPath = new File("").getAbsolutePath();
 System.err.println("[FileUtil] 工程根目录探测失败，使用当前工作目录: " + projectPath);
 }
 return projectPath + "/";
 }

 private static String readProjectPathFromLocalProperties(File file) {
 if (file == null || !file.exists()) {
 return null;
 }
 Properties properties = new Properties();
 try (FileInputStream fileInputStream = new FileInputStream(file)) {
 properties.load(fileInputStream);
 } catch (Exception e) {
 e.printStackTrace();
 return null;
 }
 return properties.getProperty("projectpath");
 }

 /**
 * 通过 FileUtil.class 所在的 class 输出目录，向上反推工程根目录。
 * 典型路径：<root>/code/build/intermediates/javac/.../classes/com/ng/code/util/FileUtil.class
 * 我们只需找到路径中的 "code" 段，取其父目录即可。
 */
 private static String autoDetectProjectRoot() {
 try {
 URL location = FileUtil.class.getProtectionDomain().getCodeSource().getLocation();
 if (location == null) {
 return null;
 }
 File f = new File(location.toURI());
 // 一直向上找，直到遇到名为 "code" 的目录，其父目录即工程根
 File cur = f;
 while (cur != null) {
 if ("code".equals(cur.getName())) {
 File parent = cur.getParentFile();
 return parent == null ? null : parent.getAbsolutePath();
 }
 cur = cur.getParentFile();
 }
 return null;
 } catch (Exception e) {
 return null;
 }
 }
}","apply_mode":"apply_only"}},"timestamp":1778729484,"type":"TOOL_CALL_ARGS"}

