{"rawEvent":{"message_id":"019e253be5cf7e0f83301b9ccdde1630","conversation_id":"019e24746cf87e7bb37671ae61701f24","tool_call_id":"tooluse_AlOc3cpGIqAIu5po8w5JmF","document":{"file_path":"/Users/garyznjiang/AndroidStudioProjects/other/个人/NgLeetCode/code/src/main/java/com/ng/code/util/ProblemUtil.java","sub_content":"ProblemUtil.java","sub_content_event":"open_editor","sub_content_event_value":"/Users/garyznjiang/AndroidStudioProjects/other/个人/NgLeetCode/code/src/main/java/com/ng/code/util/ProblemUtil.java","sub_content_tip":"/Users/garyznjiang/AndroidStudioProjects/other/个人/NgLeetCode/code/src/main/java/com/ng/code/util/ProblemUtil.java","old_string":"    /**
     * 抽题机
     * <p>
     * level: 1 2 3 三个难度
     */
    public static void getRandomTest(int num, int level) {
        LogUtil.print("抽取 " + num + " 道题目");
        Set<Class<?>> codeSet = getClassSet(Constants.CODE_PKG_NAME);
        ArrayList<Class<?>> list = new ArrayList(codeSet);
        if (list.isEmpty()) {
            LogUtil.print("题库为空，未扫到任何题目类，跳过抽题。请检查 Constants.JAVA_DIR_PATH: " + Constants.JAVA_DIR_PATH);
            return;
        }
        List<Integer> repeatList = new ArrayList<>();

        int result = 0;
        while (result < num) {
            int randomIndex = new Random().nextInt(list.size());
            while (repeatList.contains(randomIndex)) {
                randomIndex = new Random().nextInt(list.size());
            }
            repeatList.add(randomIndex);
            Class<?> randomItem = list.get(randomIndex);

            boolean fitLevel = false;
            switch (level) {
                case 1:
                    fitLevel = randomItem.getSimpleName().startsWith("Ⅰ_");
                    break;
                case 2:
                    fitLevel = randomItem.getSimpleName().startsWith("Ⅱ_");
                    break;
                case 3:
                    fitLevel = randomItem.getSimpleName().startsWith("Ⅲ_");
                    break;
                default:
                    continue;
            }

            if (fitLevel) {
                Annotation[] annos = randomItem.getAnnotations();
                for (Annotation anno : annos) {
                    Solution solution = (Solution) anno;
                    if (solution.easy() + solution.hard() == 0) {
                        LogUtil.print(
                            (result + 1) + " " + randomItem.getSimpleName() + " easy:" +
                                solution.easy() + " hard:" + solution.hard());
                        result++;
                    }
                }
            }
        }
    }","new_string":"    /**
     * 抽题机
     * <p>
     * level: 1 2 3 三个难度
     * <p>
     * 异步执行：内部启动一个子线程执行扫题/抽题，方法立即返回，
     * 这样可以与 {@link #refreshLocalProjects()} 中的 copyJavaToAssets 并发，加速启动。
     */
    public static void getRandomTest(final int num, final int level) {
        Thread thread = new Thread(new Runnable() {
            @Override
            public void run() {
                doGetRandomTest(num, level);
            }
        }, "ProblemUtil-getRandomTest");
        thread.start();
    }

    private static void doGetRandomTest(int num, int level) {
        LogUtil.print("抽取 " + num + " 道题目");
        Set<Class<?>> codeSet = getClassSet(Constants.CODE_PKG_NAME);
        ArrayList<Class<?>> list = new ArrayList(codeSet);
        if (list.isEmpty()) {
            LogUtil.print("题库为空，未扫到任何题目类，跳过抽题。请检查 Constants.JAVA_DIR_PATH: " + Constants.JAVA_DIR_PATH);
            return;
        }
        List<Integer> repeatList = new ArrayList<>();

        int result = 0;
        while (result < num) {
            int randomIndex = new Random().nextInt(list.size());
            while (repeatList.contains(randomIndex)) {
                randomIndex = new Random().nextInt(list.size());
            }
            repeatList.add(randomIndex);
            Class<?> randomItem = list.get(randomIndex);

            boolean fitLevel = false;
            switch (level) {
                case 1:
                    fitLevel = randomItem.getSimpleName().startsWith("Ⅰ_");
                    break;
                case 2:
                    fitLevel = randomItem.getSimpleName().startsWith("Ⅱ_");
                    break;
                case 3:
                    fitLevel = randomItem.getSimpleName().startsWith("Ⅲ_");
                    break;
                default:
                    continue;
            }

            if (fitLevel) {
                Annotation[] annos = randomItem.getAnnotations();
                for (Annotation anno : annos) {
