package com.ng.code;
import com.ng.base.utils.LogUtil;
import com.ng.code.util.BasePracticeClass;

public class PracticeClass extends BasePracticeClass {

    @Override
    public void run() {
        int[] array = new int[]{9, 7, 6, 5, 3, 1, 10, 4, 9, 8, -1};
        sort(array);
        LogUtil.print(array);
    }

    private void sort(int[] array) {
        int index = 1;
        while (index < array.length) {
            int preIndex = index - 1;
            int now = array[preIndex + 1];

            while (preIndex >= 0 && array[preIndex] > array[preIndex + 1]) {
                array[preIndex + 1] = array[preIndex];
                preIndex--;
            }


            array[preIndex + 1] = now;

            index++;

        }

    }


}

