public class PracticeClass {

 public static void main(String[] args) {
 int[] array = new int[]{9, 7, 6, 5, 3, 1, 10, 4, 9, 8, -1};
 System.out.println("原始数组:");
 printArray(array);
 sort(array, 0, array.length - 1);
 System.out.println("排序后:");
 printArray(array);

 // 测试其他用例
 int[] test1 = new int[]{5, 2, 8, 1, 9};
 System.out.println("\n测试用例1:");
 printArray(test1);
 sort(test1, 0, test1.length - 1);
 printArray(test1);
 }

 private static void sort(int[] array, int start, int end) {
 if (start >= end) {
 return;
 }
 int left = start;
 int right = end;
 int target = array[start];

 while (left < right) {
 // 从右向左找第一个小于target的元素
 while (left < right && array[right] >= target) {
 right--;
 }
 // 从左向右找第一个大于target的元素
 while (left < right && array[left] <= target) {
 left++;
 }
 // 交换找到的两个元素
 if (left < right) {
 int temp = array[left];
 array[left] = array[right];
 array[right] = temp;
 }
 }

 // 将基准元素放到正确位置
 array[start] = array[left];
 array[left] = target;

 // 递归排序左右子数组
 sort(array, start, left - 1);
 sort(array, left + 1, end);
 }

 private static void printArray(int[] array) {
 for (int num : array) {
 System.out.print(num + " ");
 }
 System.out.println();
