package com.ng.code;
import java.util.LinkedList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicStampedReference;

import com.ng.base.utils.ListNode;
import com.ng.base.utils.LogUtil;
import com.ng.base.utils.TreeNode;
import com.ng.code.util.BasePracticeClass;

public class PracticeClass extends BasePracticeClass {

    @Override
    public void run() {
        int[] array = new int[]{9, 7, 6, 5, 3, 1, 10, 4, 9, 8, -1};
        sort(array, 0, array.length - 1);
        LogUtil.print(array);
    }

    private void sort(int[] array, int start, int end) {
        if (start >= end) {
            return;
        }
        int left = start;
        int right = end;
        int target = array[start];

        while (left < right) {
            while (left < right && array[left] <= target) {
                left++;
            }
            while (left < right && array[right] >= target) {
                right--;
            }
            if (left < right && array[left] == array[right]) {
                left++;
                right--;
            } else {
                int temp = array[left];
                array[left] = array[right];
                array[right] = temp;
            }
        }

        if (left - 1 > start) {
            sort(array, start, left - 1);
        }
        if (right + 1 < end) {
            sort(array, right + 1, end);
        }


    }


}

